Hypothesis OPNEWX : PMES.opnew_x_spec L HI.
Definition Cred (cr0 : credit) (i : nat) (E : env) (cr : credit) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 4 "S00$cr0;R'_:$i;R+H$E;R+aO$cr;R'_:!3+7'_:#1-5RN$~R+5'_:!1'^A#32#4!2'f2/L;#4").

Lemma push_back_grow_x : forall (LB : list (Z * Z)) (cr : credit) (o cap p c sp r : Z) (s : list Z),
  PML.cps_heap L HI PML.PC_STR_PUSH_BACK r sp PMS.STR_SCR LB cr
      (fun R M => (24 <= cap /\ Z.of_nat (length s) + 1 = cap) /\ PML.entry L R M sp r PMS.STR_SCR /\ PML.a0 R o /\ PML.a1 R c /\ 0 <= c < 256 /\ PML.str_at M o (PML.SLong cap p s) /\
                  In (p, cap) LB /\ PML.obj_on_stack L sp o 24 /\ hl_k_per_malloc L <= fst cr)
      (fun R M R' M' LB' cr' LBk W =>
         (exists p', let cap' := PML.grow_cap cap (Z.of_nat (length (s ++ [c]))) in
